key = "secret_key"
print(decode_json_web_token(token, key))  # Expected output: {'name': 'John Doe', 'exp': 1623244009}

# Test with expired token
expired_token = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJuYW1lIjoiSm9obiBEb2UiLCJleHAiOjE0MDAwMDB0MDB9"
print(decode_json_web_token(expired_token, key))  # Expected output: {}

# Test with invalid token format
invalid_token = "invalid_token"
print(decode_json_web_token(invalid_token, key))  # Expected output: {}

# Test with empty token or key
print(decode_json_web_token("", key))           # Expected output: {}
print(decode_json_web_token(token, ""))         # Expected output: {}
